\title{The Chromatic Sum of Finite Graphs:\\
Foundations, Exact Formulas, and Contrarian Counterexamples}
\author{Aristotle}
\date{2026-07-11}

\begin{document}
\maketitle

\begin{abstract}
The \emph{chromatic sum} $\Sig(G)$ of a finite simple graph $G$ is the minimum,
over all proper colorings using positive integer colors, of the total sum of
colors assigned to vertices. Unlike the chromatic number $\chi(G)$, which
measures only the size of the color palette, the chromatic sum is sensitive to
the multiplicity with which each color is used, and its optimal colorings behave
counterintuitively. We develop the chromatic sum from first principles: we
establish that the defining minimum is attained, prove the universal lower-bound
property, and derive the fundamental structural facts $\Sig(G) \geq |V|$,
equality for the edgeless graph, and monotonicity under subgraph inclusion. We
then compute two exact closed forms: $\Sig(K_n) = \binom{n+1}{2} = n(n+1)/2$ for
the complete graph, and $\Sig(K_{1,n}) = n + 2$ for the star, the simplest
nontrivial family of trees. As a corollary we obtain $\Sig(K_n) = |V| + |E|$. We
use these formulas to \emph{refute} two natural conjectures: (i) the closed form
$\Sig(G) = |V| + |E|$, though valid for edgeless graphs, single edges, and
\emph{all} complete graphs, fails already for the three-vertex path $P_3$ (a
forest), where $\Sig = 4 \neq 5$; and (ii) a proper coloring achieving the
optimal number of colors need not minimize the color sum, again witnessed by
$P_3$. These results form the combinatorial substrate of the conjectured
complexity dichotomy for the Chromatic Sum problem on $H$-free graphs, and the
star formula is a first exact result on the tractable (forest) side.
\end{abstract}

\noindent\textbf{Keywords:} chromatic sum, minimum color sum, graph coloring,
proper coloring, triangular number, star graph, path graph, complexity
dichotomy, $H$-free graphs, forests.

\section{Introduction}

Graph coloring is among the oldest and most influential topics in
combinatorics. In its classical form one seeks the \emph{chromatic number}
$\chi(G)$: the least number of colors needed so that adjacent vertices receive
distinct colors. Yet in many applications colors are not interchangeable
tokens; they carry \emph{cost}. In scheduling a color may be a time slot; in
frequency assignment higher channels are scarcer and more expensive. These
applications motivate the \textbf{chromatic sum} (also called the
\emph{minimum color sum} or \emph{vertex coloring sum}):
\[
\Sig(G) = \min_{c} \sum_{v \in V} c(v),
\]
the minimum total color over all proper colorings $c : V \to \{1,2,3,\dots\}$.

The chromatic sum superficially resembles the chromatic number---both are
minimized by ``using small colors''---but it is a genuinely finer invariant. It
depends on how many vertices receive each color, not merely on how many colors
appear. Our contributions are: foundational theory
(\S\ref{sec:foundations}); the exact formulas $\Sig(K_n)=n(n+1)/2$ and
$\Sig(K_{1,n})=n+2$ (\S\ref{sec:formulas}); two refuted conjectures
(\S\ref{sec:contrarian}); and the surrounding complexity context
(\S\ref{sec:dichotomy}--\S\ref{sec:discussion}).

\section{Preliminaries and Notation}

Throughout, $G = (V,E)$ is a finite simple graph. We write $u \sim v$ when
$\{u,v\} \in E$, $|V|$ for the number of vertices, and $|E|$ for the number of
edges. The \emph{complete graph} $K_n$ has all pairs adjacent; the
\emph{edgeless graph} $\overline{K_n}$ has $E=\varnothing$; the \emph{path}
$P_3$ has vertices $\{0,1,2\}$ and edges $\{0,1\},\{1,2\}$; the \emph{star}
$K_{1,n}$ has a center adjacent to $n$ leaves with no edges among the leaves.
Note $P_3 = K_{1,2}$. Colors are the positive integers $\{1,2,3,\dots\}$.

\section{The Chromatic Sum: Definition and Basic Theory}
\label{sec:foundations}

\subsection{Definitions}

\begin{definition}[Proper coloring]
A function $c : V \to \mathbb{Z}_{\geq 1}$ is a \emph{proper coloring} of $G$ if
(i) $c(v) \geq 1$ for all $v$, and (ii) $c(u) \neq c(v)$ whenever $u \sim v$.
\end{definition}

\begin{definition}[Color sum]
The \emph{color sum} of a coloring $c$ is $\colorSum(c) = \sum_{v \in V} c(v)$.
\end{definition}

\begin{definition}[Chromatic sum]
The \emph{chromatic sum} of $G$ is
$\Sig(G) = \min\{\, \colorSum(c) : c \text{ a proper coloring of } G \,\}$,
the least achievable color sum. We show below that this infimum is attained.
\end{definition}

\subsection{Existence and attainment}

\begin{lemma}[A proper coloring always exists]
\label{lem:exists}
Every finite graph $G$ admits a proper coloring.
\end{lemma}
\begin{proof}[Proof sketch]
Enumerate the vertices $v_0,\dots,v_{n-1}$ and set $c(v_i) = i+1$. All colors
are $\geq 1$, and distinct vertices receive distinct colors, so adjacent
vertices in particular differ.
\end{proof}

\begin{theorem}[Attainment]
\label{thm:attain}
There is a proper coloring $c^\star$ with $\colorSum(c^\star) = \Sig(G)$.
\end{theorem}
\begin{proof}[Proof sketch]
By Lemma~\ref{lem:exists} the set of achievable color sums is a nonempty subset
of $\mathbb{N}$; every such set has a least element, which is $\Sig(G)$ by
definition.
\end{proof}

\subsection{The universal property}

\begin{proposition}[Lower bound by any coloring]
\label{prop:lb}
For every proper coloring $c$, $\Sig(G) \leq \colorSum(c)$.
\end{proposition}

\begin{proposition}[Universal lower bound]
\label{prop:ulb}
If $k \in \mathbb{N}$ satisfies $k \leq \colorSum(c)$ for every proper coloring
$c$, then $k \leq \Sig(G)$.
\end{proposition}
\begin{proof}[Proof sketch]
Proposition~\ref{prop:lb} holds because $\Sig(G)$ is the minimum of the set. For
Proposition~\ref{prop:ulb}, apply the hypothesis to the optimal coloring
$c^\star$ of Theorem~\ref{thm:attain}: $k \leq \colorSum(c^\star) = \Sig(G)$.
\end{proof}

To prove $\Sig(G)=m$ it thus suffices to exhibit one coloring of sum $m$ and to
argue every proper coloring has sum $\geq m$.

\subsection{Structural bounds}

\begin{theorem}[Vertex floor]
\label{thm:floor}
For every graph $G$ on $n$ vertices, $\Sig(G) \geq n$.
\end{theorem}
\begin{proof}[Proof sketch]
Each of the $n$ vertices has color $\geq 1$, so any color sum is
$\geq \sum_v 1 = n$; apply Proposition~\ref{prop:ulb}.
\end{proof}

\begin{theorem}[Edgeless graph]
For the edgeless graph on $n$ vertices, $\Sig(\overline{K_n}) = n$.
\end{theorem}
\begin{proof}[Proof sketch]
The constant coloring $c \equiv 1$ is proper with sum $n$, so $\Sig \leq n$;
combine with Theorem~\ref{thm:floor}.
\end{proof}

\begin{theorem}[Monotonicity]
If $E(H) \subseteq E(G)$ on the same vertex set, then $\Sig(H) \leq \Sig(G)$.
\end{theorem}
\begin{proof}[Proof sketch]
Every proper coloring of $G$ is proper for $H$, since $H$'s constraints are a
subset of $G$'s. Hence for any proper $c$ of $G$, $\Sig(H) \leq \colorSum(c)$;
minimize over $c$.
\end{proof}

\section{Exact Formulas}
\label{sec:formulas}

\subsection{The complete graph}

\begin{lemma}[Proper $=$ injective on $K_n$]
\label{lem:injtop}
A coloring $c$ of $K_n$ is proper iff $c(v) \geq 1$ for all $v$ and $c$ is
injective.
\end{lemma}
\begin{proof}[Proof sketch]
Adjacency in $K_n$ means ``distinct vertices,'' so properness reads ``distinct
vertices have distinct colors,'' i.e. injectivity.
\end{proof}

\begin{lemma}[Minimality of the initial segment]
\label{lem:minseg}
If $T \subseteq \mathbb{Z}_{\geq 1}$ is finite with $|T| = k$, then
$\sum_{x \in T} x \geq 1 + 2 + \cdots + k = k(k+1)/2$.
\end{lemma}
\begin{proof}[Proof sketch]
Induct on $|T|$, removing $m = \max T$. Since $T \subseteq \{1,\dots,m\}$ we have
$k \leq m$. The remaining $k-1$ elements sum to at least $1+\cdots+(k-1)$ by
induction, and $m \geq k$; add.
\end{proof}

\begin{lemma}[Injective lower bound]
\label{lem:injlb}
Any injective positive coloring $c$ of an $n$-vertex graph satisfies
$\colorSum(c) \geq n(n+1)/2$.
\end{lemma}
\begin{proof}[Proof sketch]
The image $c(V)$ is a set of $n$ distinct positive integers whose sum equals
$\colorSum(c)$; apply Lemma~\ref{lem:minseg}.
\end{proof}

\begin{theorem}[Chromatic sum of the complete graph]
\label{thm:top}
For all $n$, $\Sig(K_n) = n(n+1)/2$.
\end{theorem}
\begin{proof}[Proof sketch]
\emph{Upper bound:} the coloring $c(v_i) = i+1$ is injective and positive, hence
proper (Lemma~\ref{lem:injtop}), with sum $n(n+1)/2$. \emph{Lower bound:} every
proper coloring is injective, so Lemma~\ref{lem:injlb} gives sum
$\geq n(n+1)/2$; conclude via Proposition~\ref{prop:ulb}.
\end{proof}

\begin{corollary}[Vertices-plus-edges for $K_n$]
\label{cor:VE}
$\Sig(K_n) = |V| + |E|$.
\end{corollary}
\begin{proof}[Proof sketch]
$K_n$ has $|V|=n$ and $|E|=\binom{n}{2}$, so
$|V|+|E| = n + n(n-1)/2 = n(n+1)/2 = \Sig(K_n)$.
\end{proof}

\subsection{The star}

\begin{theorem}[Chromatic sum of the star]
\label{thm:star}
For every $n \geq 1$, $\Sig(K_{1,n}) = n + 2$.
\end{theorem}
\begin{proof}[Proof sketch]
\emph{Upper bound:} color the center $2$ and every leaf $1$. Leaves are mutually
non-adjacent, so this is proper, with sum $2 + n = n+2$. \emph{Lower bound:} fix
a proper coloring $c$ and split on $c(\text{center})$. If $c(\text{center})=1$,
each leaf is $\geq 2$, giving total $\geq 1 + 2n \geq n+2$. If
$c(\text{center}) \geq 2$, each of the $n$ leaves is $\geq 1$, giving total
$\geq n + 2$. Apply Proposition~\ref{prop:ulb}.
\end{proof}

The worse strategy---center $1$, leaves $2$---costs $1+2n$, nearly double $n+2$.
Setting $n=2$ recovers $\Sig(P_3)=4$.

\section{Contrarian Results: Two Refuted Conjectures}
\label{sec:contrarian}

Corollary~\ref{cor:VE} gives $\Sig=|V|+|E|$ for all complete graphs; it also
holds for the edgeless graph and the single edge. This invites a general
conjecture, which we demolish.

\begin{theorem}[Chromatic sum of $P_3$]
\label{thm:p3}
$\Sig(P_3) = 4$.
\end{theorem}
\begin{proof}[Proof sketch]
\emph{Upper bound:} endpoints $1$, center $2$ is proper with sum $4$.
\emph{Lower bound:} with $c(0)\neq c(1)$ and $c(1)\neq c(2)$: if $c(1)=1$ then
$c(0),c(2)\geq 2$ and the sum is $\geq 5$; if $c(1)\geq 2$ the sum is
$\geq 1+2+1 = 4$.
\end{proof}

\begin{theorem}[Refutation of $\Sig = |V| + |E|$]
It is false that $\Sig(G) = |V| + |E|$ for all finite graphs $G$.
\end{theorem}
\begin{proof}
For $P_3$, $|V|+|E| = 3+2 = 5$, whereas $\Sig(P_3)=4$ by Theorem~\ref{thm:p3}.
\end{proof}

The failure occurs at the smallest tree with a branch vertex---a forest. The
high-degree vertex should receive an expensive color so its neighbors can share
the cheap one.

\begin{theorem}[A $\chi$-optimal coloring need not be sum-optimal]
There is a proper coloring of $P_3$ using exactly $2$ colors whose color sum
exceeds $\Sig(P_3)$.
\end{theorem}
\begin{proof}
Color endpoints $2$ and center $1$: proper, uses colors $\{1,2\}$, sum
$2+1+2 = 5 > 4 = \Sig(P_3)$.
\end{proof}

Thus minimizing the number of colors ($\chi$) and minimizing the sum of colors
($\Sig$) are distinct optimization problems.

\section{Application: The Conjectured Complexity Dichotomy}
\label{sec:dichotomy}

For a fixed forbidden pattern $H$, an $H$-free graph contains no induced copy of
$H$. The \emph{Chromatic Sum problem} asks whether $\Sig(G)$ is at most a given
budget.

\begin{conjecture}[Chromatic Sum dichotomy]
For every fixed graph $H$: if $H$ is a forest, the Chromatic Sum problem on
$H$-free graphs is solvable in polynomial time; if $H$ contains a cycle, it is
NP-complete.
\end{conjecture}

A single structural feature of $H$---the presence or absence of a cycle---is
conjectured to separate tractable from intractable. Our formulas populate the
forest (tractable) side with exact answers: the star family is solved completely
by $\Sig(K_{1,n}) = n+2$. The refutations of \S\ref{sec:contrarian} show that
even on this easy side the problem cannot be reduced to counting edges or to
chromatic-number heuristics. Complexity-theoretic statements themselves require
a formal model of computation and lie beyond the combinatorial scope here.

\section{Discussion and Future Work}
\label{sec:discussion}

\paragraph{Summary.} We built $\Sig(G)$ from first principles (attained minimum,
universal property, floor, edgeless equality, monotonicity), computed
$\Sig(K_n)=n(n+1)/2=|V|+|E|$ and $\Sig(K_{1,n})=n+2$, and used $P_3$ to refute
both the closed form $\Sig=|V|+|E|$ and the belief that a $\chi$-optimal
coloring minimizes cost.

\paragraph{Future directions.}
\begin{enumerate}[leftmargin=*]
\item \textbf{General forest formula.} A polynomial dynamic-programming
recursion for $\Sig$ on arbitrary trees (track optimal subtree cost under each
possible root color).
\item \textbf{Bipartite lower bounds.} Bounds of the form
$\Sig(G) \geq |V| + (\text{matching number})$ and exact values on $K_{m,n}$.
\item \textbf{The $\Sig$-vs-$\chi$ gap.} Families (e.g. balanced binary trees)
where every minimum-sum coloring provably uses more than $\chi=2$ colors.
\item \textbf{Toward the hard side.} Identify the smallest cyclic patterns for
which intractability is expected and the path/star gadgets that would drive a
hardness reduction.
\end{enumerate}

\paragraph{Closing remark.} The chromatic sum recasts coloring as economics: its
optima sacrifice busy, high-degree vertices to expensive colors so their many
neighbors can crowd onto cheap ones---the principle behind the triangular
number, the $n+2$ for stars, and the collapse of the $|V|+|E|$ heuristic.

