function CHROMATIC_SUM_BRUTEFORCE(n, edges):
    best <- +infinity;  witness <- none
    for each coloring in {1..n}^n:
        if for every edge (u,v): coloring[u] != coloring[v]:
            s <- sum(coloring)
            if s < best: best <- s; witness <- coloring
    return (best, witness)

function CHROMATIC_SUM_TREE(tree, root, palette):
    order <- post-order DFS of tree from root
    for v in reverse(order):            # children before parents
        for colour k in 1..palette:
            dp[v][k] <- k
            for each child u of v:
                dp[v][k] <- dp[v][k] + min over k' != k of dp[u][k']
    return min over k of dp[root][k]
